import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int k = (int) st.nval;
        st.nextToken(); long th = (long) st.nval;
        st.nextToken(); int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        // Window sum s over the last k minutes; average > th  <=>  s > th * k.
        long s = 0;
        int count = 0;
        for (int i = 0; i < n; i++) {
            s += a[i];
            if (i >= k) s -= a[i - k];
            if (i >= k - 1 && s > th * k) count++;
        }
        System.out.println(count);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var k, n int
	var th int64
	fmt.Fscan(in, &k, &th, &n)
	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	// Window sum s over the last k minutes; average > th  <=>  s > th * k.
	var s int64
	count := 0
	for i := 0; i < n; i++ {
		s += a[i]
		if i >= k {
			s -= a[i-k]
		}
		if i >= k-1 && s > th*int64(k) {
			count++
		}
	}
	fmt.Println(count)
}
